actions.set_conversation_response:
{%- set names = {'clear-night':'clear','cloudy':'cloudy','exceptional':'unusual out there','fog':'foggy','hail':'hailing','lightning':'stormy','lightning-rainy':'stormy','partlycloudy':'partly cloudy','pouring':'pouring','rainy':'rainy','snowy':'snowy','snowy-rainy':'wet with rain and snow','sunny':'sunny','windy':'windy','windy-variant':'windy'} -%}
{%- set days = fc['weather.forecast_home'].forecast -%}
{%- set target = now().date() + timedelta(days=1) if trigger.id == 'tomorrow' else now().date() -%}
{%- set ns = namespace(d=none) -%}
{%- for x in days if ns.d is none and as_local(as_datetime(x.datetime)).date() == target -%}{%- set ns.d = x -%}{%- endfor -%}
{%- set d = ns.d or days[0] -%}
{%- set p = d.precipitation | float(0) -%}
{%- set kind = 'snow' if d.condition in ['snowy', 'snowy-rainy'] else 'rain' -%}
{%- set wet = ', with about ' ~ (p | round(1)) ~ ' inches of ' ~ kind if p >= 0.05 else ', and no rain or snow is expected' -%}
{%- if trigger.id == 'tomorrow' -%}
Tomorrow will be {{ names.get(d.condition, d.condition) }}, with a high of {{ d.temperature | round(0) | int }} and a low of {{ d.templow | round(0) | int }}{{ wet }}.
{%- else -%}
It's {{ state_attr('weather.forecast_home', 'temperature') | round(0) | int }} degrees and {{ names.get(states('weather.forecast_home'), states('weather.forecast_home')) }}. Today's high is {{ d.temperature | round(0) | int }} with a low of {{ d.templow | round(0) | int }}{{ wet }}.
{%- endif -%}
